@using sv_1f6b85041c384091b211b99dd1bce6b9.Services
@inject CascadingValueSource<WarehouseState> WarehouseSource
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label text-white mb-1" for="warehouseDropdown">Current Warehouse</label>
    <select id="warehouseDropdown"
            class="form-select form-select-sm"
            value="@_selectedId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-001";

    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    protected override void OnInitialized()
    {
        if (Warehouse is not null)
        {
            _selectedId = Warehouse.WarehouseId;
        }
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-001";
        var match = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == _selectedId);

        var newState = new WarehouseState
        {
            WarehouseId = match.Id ?? _selectedId,
            WarehouseName = match.Name ?? _selectedId
        };

        // Push to all [CascadingParameter] subscribers across render modes.
        await WarehouseSource.NotifyChangedAsync(newState);
    }
}

@using sv_1f6b85041c384091b211b99dd1bce6b9.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="badge rounded-pill @BadgeClass">@AlertService.CurrentAlertCount</span>

@code {
    private Action? _handler;

    private string BadgeClass => AlertService.CurrentAlertCount switch
    {
        > 10 => "bg-danger",
        > 5 => "bg-warning text-dark",
        > 0 => "bg-info",
        _ => "bg-secondary"
    };

    protected override void OnInitialized()
    {
        // Event fires from the polling component's InvokeAsync context,
        // so we also wrap in InvokeAsync to be safe on background threads.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

