@page "/dashboard"
@using sv_1f6b85041c384091b211b99dd1bce6b9.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @(Warehouse?.WarehouseName ?? "None selected")
                    <span class="text-muted fs-6">(@(Warehouse?.WarehouseId ?? "—"))</span>
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-2">
                    <AlertBadge />
                </p>
                <p class="text-muted small">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">Active</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Stopped</span>
                    }
                </p>
                <p class="text-muted small">Last checked: @_lastChecked?.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime? _lastChecked;
    private Action? _handler;

    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        // Restart polling whenever the cascaded warehouse changes.
        await StopPollingAsync();
        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        var warehouseId = Warehouse?.WarehouseId ?? "WH-001";

        // Fire an immediate first fetch so the UI doesn't start blank.
        await AlertService.RefreshAsync(warehouseId);
        _lastChecked = DateTime.Now;
        _isPolling = true;

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            try
            {
                while (await timer.WaitForNextTickAsync(token))
                {
                    await AlertService.RefreshAsync(warehouseId);
                    await InvokeAsync(() =>
                    {
                        _lastChecked = DateTime.Now;
                        StateHasChanged();
                    });
                }
            }
            catch (OperationCanceledException) { }
        }, token);
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _isPolling = false;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

